# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ATMOSFERDE NEM TÜRLERİ: MUTLAK, MAKSİMUM VE BAĞIL NEM (COĞ.9.3.2)</text>\n  <rect x="20" y="45" width="210" height="110" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. MUTLAK NEM (g/m³)</text>\n  <text x="125" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">Havadaki Mevcut Su Buharı</text>\n  <text x="125" y="108" text-anchor="middle" font-size="10" fill="#1d4ed8">Su kaynağı + Sıcaklık arttıkça</text>\n  <text x="125" y="124" text-anchor="middle" font-size="10" fill="#1d4ed8">buharlaşma ve mutlak nem artar.</text>\n  <text x="125" y="142" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">(Ekvator ve kıyılarda yüksek)</text>\n  <rect x="245" y="45" width="210" height="110" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">2. MAKSİMUM NEM (g/m³)</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">Havanın Nem Taşıma Kapasitesi</text>\n  <text x="350" y="108" text-anchor="middle" font-size="10" fill="#78350f">Sıcaklıkla DOĞRU orantılıdır!</text>\n  <text x="350" y="124" text-anchor="middle" font-size="10" fill="#78350f">Isınan hava genleşir, kapasitesi</text>\n  <text x="350" y="142" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">büyür (Çöllerde çok yüksek).</text>\n  <rect x="470" y="45" width="210" height="110" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. BAĞIL (NİSPİ) NEM (%)</text>\n  <text x="575" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">Havanın Doyma Oranı (Yağış İhtimali)</text>\n  <text x="575" y="108" text-anchor="middle" font-size="10" fill="#166534">Sıcaklıkla TERS orantılıdır!</text>\n  <text x="575" y="124" text-anchor="middle" font-size="10" fill="#166534">%100 olunca hava doyar ve</text>\n  <text x="575" y="142" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">yoğuşma / yağış başlar.</text>\n  <rect x="20" y="168" width="660" height="76" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="194" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">TEMEL FORMÜL: Bağıl Nem (%) = (Mutlak Nem / Maksimum Nem) × 100</text>\n  <text x="350" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">Sıcaklık Artarsa → Maksimum Nem (Kapasite) Artar → Bağıl Nem (%) Düşer → Yağış İhtimali Azalır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ATMOSFERDE YOĞUŞMA TÜRLERİ (YERDE VE GÖKYÜZÜNDE)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">GÖKYÜZÜNDE (YÜKSEKTE) YOĞUŞMA</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">• Bulut (0 °C üstü / altı): Yükseklerde asılı su</text>\n  <text x="45" y="112" font-size="10.5" fill="#1d4ed8">damlacıkları veya buz kristalleri (Sirüs, Kümülüs, Stratüs).</text>\n  <text x="35" y="138" font-size="11" font-weight="bold" fill="#1e3a8a">• Yağmur (&gt; 0 °C): Buluttaki su damlacıklarının</text>\n  <text x="45" y="154" font-size="10.5" fill="#1d4ed8">büyüyerek yer çekimiyle sıvı hâlde düşmesi.</text>\n  <text x="35" y="180" font-size="11" font-weight="bold" fill="#1e3a8a">• Kar (&lt; 0 °C): Su buharının 0 °C altında altıgen</text>\n  <text x="45" y="196" font-size="10.5" fill="#1d4ed8">buz kristalleri hâlinde yoğuşarak yere inmesi.</text>\n  <text x="35" y="220" font-size="11" font-weight="bold" fill="#b91c1c">• Dolu (&lt; 0 °C): Dikey hava akımıyla ani donan buz.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">YERYÜZÜNDE (ZEMİNDE) YOĞUŞMA</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#14532d">• Sis (&gt; 0 °C): Yere temas eden ılık ve nemli havanın</text>\n  <text x="385" y="112" font-size="10.5" fill="#166534">soğuk zemin üzerinde su damlacıklarına dönüşmesi.</text>\n  <text x="375" y="138" font-size="11" font-weight="bold" fill="#14532d">• Çiy (&gt; 0 °C): Bahar ve yaz sabahları bitkiler ve</text>\n  <text x="385" y="154" font-size="10.5" fill="#166534">cisimler üzerinde oluşan su damlacıkları.</text>\n  <text x="375" y="180" font-size="11" font-weight="bold" fill="#14532d">• Kırağı (&lt; 0 °C): 0 °C altında soğuk yüzeylerde</text>\n  <text x="385" y="196" font-size="10.5" fill="#166534">oluşan ince buz kristalleri tabakası.</text>\n  <text x="375" y="220" font-size="11" font-weight="bold" fill="#b45309">• Kırç (&lt; 0 °C): Aşırı soğukta dalları saran kalın buz.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">OLUŞUM ŞEKİLLERİNE GÖRE YAĞIŞ TÜRLERİ (COĞ.9.3.2)</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. KONVEKSİYONEL (YÜKSELİM)</text>\n  <text x="125" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">Isınan Havanın Yükselmesi</text>\n  <path d="M 75 145 L 75 105 M 125 145 L 125 105 M 175 145 L 175 105" stroke="#dc2626" stroke-width="2.5"/>\n  <text x="125" y="164" text-anchor="middle" font-size="10" fill="#1d4ed8">Zemin ısınır → Hava yükselir</text>\n  <text x="125" y="180" text-anchor="middle" font-size="10" fill="#1d4ed8">ve soğur → Sağanak yağış.</text>\n  <text x="125" y="202" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">Dünya: Ekvator (Yıl boyu)</text>\n  <text x="125" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Türkiye: İç Anadolu (Kırkikindi)</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. OROGRAFİK (YAMAÇ)</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">Dağ Yamacında Yükselme</text>\n  <polygon points="275,148 355,102 425,148" fill="#bbf7d0" stroke="#15803d" stroke-width="2"/>\n  <text x="350" y="164" text-anchor="middle" font-size="10" fill="#166534">Nemli hava dağ yamacına</text>\n  <text x="350" y="180" text-anchor="middle" font-size="10" fill="#166534">çarparak yükselir ve soğur.</text>\n  <text x="350" y="202" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Dünya: Güneydoğu Asya (Muson)</text>\n  <text x="350" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Türkiye: Karadeniz ve Toroslar</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">3. CEPHE (FRONTAL)</text>\n  <text x="575" y="88" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#78350f">Sıcak ve Soğuk Hava Karşılaşması</text>\n  <line x1="505" y1="145" x2="635" y2="105" stroke="#7c3aed" stroke-width="3"/>\n  <text x="575" y="164" text-anchor="middle" font-size="10" fill="#78350f">Sıcak hava soğuk havanın</text>\n  <text x="575" y="180" text-anchor="middle" font-size="10" fill="#78350f">üzerine çıkarak soğur.</text>\n  <text x="575" y="202" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Dünya: 60° Enlemleri / Orta Kuşak</text>\n  <text x="575" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Türkiye: Akdeniz ve Kıyılar (Kış)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
